// ACRYL ADE's one difference from every other Blend: the page's root is the ACRYL IDE's workbench (`@acryldev/workspace`), not the Blends
// frame (`@acryldev/blends-frame`). `cordis.patch.yml` is generated by acrylblends (create, upgrade) with the frame's row; this script, run
// before `npm run dev` and `npm run desktop`, swaps that one row in place and leaves every other line as generated. Running it twice changes nothing.
import { readFileSync, writeFileSync } from 'node:fs'
import { fileURLToPath } from 'node:url'

const file = fileURLToPath(new URL('../cordis.patch.yml', import.meta.url))

/**
 * The overlay with the frame's root row replaced by the workbench's; `text` unchanged when it already mounts the workbench. The frame is named
 * `'@acryldev/blends-frame'` in an app made from npm, and `acryl-blends-frame` in one a desktop product is packed from (the packer installs the
 * framework's packages under their source names); the workbench gets the same form of name.
 */
export function withWorkbenchRoot(text) {
  return text.replace(
    /^( +)- id: (acryl-blends-frame|acryl-workspace)\n\1  name: ('@acryldev\/blends-frame'|acryl-blends-frame|'@acryldev\/workspace'|acryl-workspace)\n(?:\1  config:\n(?:\1    .*\n)*)?/mu,
    (_match, indent, _id, name) =>
      `${indent}- id: acryl-workspace\n${indent}  name: ${name.startsWith("'") ? "'@acryldev/workspace'" : 'acryl-workspace'}\n` +
      // `acryl ade` started in a folder passes it here: the workbench opens on that project.
      `${indent}  config:\n${indent}    openFolder: !!js process.env.ACRYL_OPEN_FOLDER\n`,
  )
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const before = readFileSync(file, 'utf8')
  const after = withWorkbenchRoot(before)
  if (after !== before) writeFileSync(file, after)
  if (!/name: (?:'@acryldev\/workspace'|acryl-workspace)$/mu.test(after)) {
    console.error('ade-root: cordis.patch.yml mounts neither the Blends frame nor the workbench; run `npx acrylblends upgrade` and try again')
    process.exit(1)
  }
}
